  "check_code": "import re
import sqlite3
from pathlib import Path


def _db_path(ws):
    return Path(ws).resolve().parent / "system" / "sap_inventory_logistics" / "state.db"


def _row(ws, cutoff_line_id, columns):
    database = _db_path(ws)
    if not database.exists():
        return None
    with sqlite3.connect(database) as connection:
        connection.row_factory = sqlite3.Row
        selected = ", ".join(columns)
        return connection.execute(
            f"SELECT {selected} FROM inventory_cutoff_lines WHERE cutoff_line_id = ?",
            (cutoff_line_id,),
        ).fetchone()


def _norm_text(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def check_superseded_version_retired(ws):
    columns = ["source_version", "review_status", "exclusion_reason"]
    row = _row(ws, "CL-2004-0628-071-V1", columns)
    if row is None:
        return {"score": 0, "detail": "The superseded cutoff line is missing."}
    reason = _norm_text(row["exclusion_reason"])
    reason_ok = "supersed" in reason and re.search(r"\b(version|source)\s*(2|two)\b", reason)
    passed = row["source_version"] == 1 and row["review_status"] == "EXCEPTION" and bool(reason_ok)
    return {
        "score": 1 if passed else 0,
        "detail": (
            "Version 1 is recorded as an exception with a reason identifying source version 2 as superseding it."
            if passed
            else f"Observed source_version={row['source_version']}, review_status={row['review_status']}, exclusion_reason={row['exclusion_reason']!r}."
        ),
    }


def check_retained_version_preserved(ws):
    columns = [
        "source_version",
        "transfer_price_usd_cents",
        "inventory_status",
        "review_status",
        "exclusion_reason",
        "reviewed_by",
        "reviewed_at",
    ]
    row = _row(ws, "CL-2004-0628-071-V2", columns)
    expected = (2, 332275381, "ON_HAND", "VALIDATED", None, "costacct.jmiller", "2004-07-14T13:22:09Z")
    observed = tuple(row[column] for column in columns) if row is not None else None
    return {
        "score": 1 if observed == expected else 0,
        "detail": "The retained version 2 row is unchanged." if observed == expected else f"Retained version changed: {observed!r}.",
    }


def check_unrelated_cutoff_preserved(ws):
    columns = [
        "transfer_id",
        "transfer_price_usd_cents",
